//! Provide a builder for the [SeaHasher] hasher for use in [HashMap::with_hasher].

use seahash::SeaHasher;
use std::hash::BuildHasher;

use rand::Rng;

/// Builder that creates a [SeaHasher], using 4 [u64]s as seeds.
/// Seeds can be provided at creation or automatically generated by supplying a random number generator to [SeaHashBuilder::new].
#[derive(Clone, Copy, Debug)]
pub struct SeaHashBuilder {
    pub seed1: u64,
    pub seed0: u64,
    pub seed2: u64,
    pub seed3: u64,
}

impl SeaHashBuilder {
    /// Create a new [SeaHashBuilder] using seeds generated by the `rng` provided.
    pub fn new<T>(rng: &mut T) -> Self
    where
        T: Rng,
    {
        Self {
            seed0: rng.next_u64(),
            seed1: rng.next_u64(),
            seed2: rng.next_u64(),
            seed3: rng.next_u64(),
        }
    }
}

impl BuildHasher for SeaHashBuilder {
    type Hasher = SeaHasher;

    fn build_hasher(&self) -> Self::Hasher {
        SeaHasher::with_seeds(self.seed0, self.seed1, self.seed2, self.seed3)
    }
}
